-- ========================================================
-- SISTEM KAS, IURAN & ADMINISTRASI WARGA RT 10 / RW 10
-- Berkas Database SQL Utama: kas-rt.sql
-- Tanggal Ekspor / Migrasi : 2026-10-19 02:13:11
-- Format Kompatibilitas    : SQLite, MySQL, MariaDB, PostgreSQL
-- Total Rekod Data         : 2153 Baris Data
--   - Pengaturan RT        : 1 Profil Aktif
--   - Daftar Warga (KK)    : 200 Kepala Keluarga
--   - Riwayat Kas & Iuran  : 1927 Catatan Transaksi
--   - Personalia Pengurus  : 15 Pengurus RT
--   - Warta Pengumuman     : 5 Pengumuman Resmi
--   - Suara & Aspirasi     : 5 Aspirasi Warga
-- ========================================================

PRAGMA foreign_keys = OFF;

-- --------------------------------------------------------
-- 1. STRUKTUR TABEL: settings (Pengaturan & Profil Wilayah RT)
-- --------------------------------------------------------
DROP TABLE IF EXISTS settings;
CREATE TABLE settings (
  id INTEGER PRIMARY KEY,
  nama_rt VARCHAR(100) NOT NULL,
  kelurahan VARCHAR(100),
  kecamatan VARCHAR(100),
  kota VARCHAR(100),
  nama_ketua_rt VARCHAR(100),
  nama_bendahara VARCHAR(100),
  nominal_iuran INTEGER NOT NULL,
  rincian_iuran TEXT,
  tahun_aktif INTEGER NOT NULL,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- --------------------------------------------------------
-- 2. STRUKTUR TABEL: warga (Daftar Kepala Keluarga / KK)
-- --------------------------------------------------------
DROP TABLE IF EXISTS warga;
CREATE TABLE warga (
  id VARCHAR(50) PRIMARY KEY,
  blok VARCHAR(50) NOT NULL,
  nama VARCHAR(150) NOT NULL,
  telp VARCHAR(50),
  status VARCHAR(50) DEFAULT 'Tetap',
  nominal_iuran INTEGER NOT NULL
);

-- --------------------------------------------------------
-- 3. STRUKTUR TABEL: transaksi (Buku Kas Masuk, Keluar & Iuran Warga)
-- --------------------------------------------------------
DROP TABLE IF EXISTS transaksi;
CREATE TABLE transaksi (
  id VARCHAR(50) PRIMARY KEY,
  tanggal DATE NOT NULL,
  jenis VARCHAR(20) NOT NULL,
  kategori VARCHAR(100) NOT NULL,
  uraian TEXT NOT NULL,
  nominal BIGINT NOT NULL,
  warga_id VARCHAR(50),
  bulan_iuran INTEGER,
  tahun_iuran INTEGER,
  metode VARCHAR(50) DEFAULT 'Tunai'
);

-- --------------------------------------------------------
-- 4. STRUKTUR TABEL: pengurus (Susunan Organisasi & Personalia RT)
-- --------------------------------------------------------
DROP TABLE IF EXISTS pengurus;
CREATE TABLE pengurus (
  id VARCHAR(50) PRIMARY KEY,
  jabatan VARCHAR(100) NOT NULL,
  kategori VARCHAR(50) NOT NULL,
  nama VARCHAR(150) NOT NULL,
  blok VARCHAR(50),
  telp VARCHAR(50),
  badge VARCHAR(50),
  badge_color VARCHAR(50),
  avatar_bg VARCHAR(50),
  tugas TEXT
);

-- --------------------------------------------------------
-- 5. STRUKTUR TABEL: pengumuman (Warta & Edaran Resmi RT)
-- --------------------------------------------------------
DROP TABLE IF EXISTS pengumuman;
CREATE TABLE pengumuman (
  id VARCHAR(50) PRIMARY KEY,
  judul VARCHAR(255) NOT NULL,
  kategori VARCHAR(100) NOT NULL,
  badge_color VARCHAR(50) DEFAULT 'emerald',
  is_pinned INTEGER DEFAULT 0,
  tanggal DATE NOT NULL,
  pengirim VARCHAR(150) NOT NULL,
  isi TEXT NOT NULL
);

-- --------------------------------------------------------
-- 6. STRUKTUR TABEL: suara_warga (Aspirasi, Masukan & Keluhan Warga)
-- --------------------------------------------------------
DROP TABLE IF EXISTS suara_warga;
CREATE TABLE suara_warga (
  id VARCHAR(50) PRIMARY KEY,
  judul VARCHAR(255) NOT NULL,
  kategori VARCHAR(100) NOT NULL,
  kategori_badge VARCHAR(50) DEFAULT 'purple',
  pengirim VARCHAR(150) NOT NULL,
  blok VARCHAR(50) NOT NULL,
  is_anonim INTEGER DEFAULT 0,
  tanggal DATE NOT NULL,
  isi TEXT NOT NULL,
  dukungan INTEGER DEFAULT 0,
  status VARCHAR(50) DEFAULT 'Menunggu',
  tanggapan_penjawab VARCHAR(150),
  tanggapan_tanggal DATE,
  tanggapan_pesan TEXT
);

-- --------------------------------------------------------
-- 7. STRUKTUR TABEL: log_perubahan (Riwayat Audit Perubahan SQL)
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS log_perubahan (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  waktu TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  aksi VARCHAR(100),
  keterangan TEXT,
  query_sql TEXT
);

